    // Width of the leading text and its gap; zero without one.
    int  lead_width() const;
    // Screen rect of the row-action glyph, empty when there is none.
    wxRect row_action_rect() const;
    const ShellTheme& m_theme;
    HeaderStyle m_style;
    HeaderIcon m_icon;
