wxString local_day(const std::string& iso)
{
    wxString text = wxString::FromUTF8(iso);
    if (!text.EndsWith("Z"))
        return text;
    text.RemoveLast();
    wxDateTime when;
    return when.ParseISOCombined(text) ? when.FromTimezone(wxDateTime::UTC).Format("%d %b") : wxString::FromUTF8(iso);
}

