{
    m_stale_timer.Stop();
    m_plater.Unbind(EVT_SLICE_STATUS_CHANGED, &CheckPrintDialog::on_slice_status_changed, this);
    m_subscription.reset();
    if (GLCanvas3D* canvas = m_preview->get_canvas3d()) {
        canvas->set_overlay_renderer(nullptr);
